<?php namespace Workspace; $p=$relProject; $dt=static fn($v)=>gmdate('Y-m-d H:i:s',(int)$v).' UTC'; ?>
<section class="panel"><h2>Очереди интеграций</h2><form method="get" class="inline"><input type="hidden" name="p" value="reliability"><label>Проект<select name="project" required><?php selectOptions($relProjects,$p) ?></select></label><button class="secondary">Открыть</button></form><p>Состояние берётся из действующих очередей, без копирования текстов сообщений, документов и токенов. Сверка после сбоя читает состояние источника, а не повторяет неизвестную запись.</p></section>
<?php if($p!==null): ?>
<section class="panel"><h2>Восстановление связи</h2><form method="post" class="inline"><?php formFields('reliability.reconcile') ?><input type="hidden" name="project_id" value="<?= (int)$p ?>"><button class="primary">Запланировать сверку проекта (MFA)</button></form><p>GitHub — актуальные связанные объекты; Servers/aaPanel — проверка хостов; Bots и Dropbox Sign — чтение состояния существующих операций. Logs — штатная очередь; исчерпанный бюджет требует отдельного решения.</p></section>
<?php foreach($relRows as $provider=>$rows): ?><section class="panel"><h2><?= h(REL_PROVIDERS[$provider]) ?></h2><div class="tablewrap"><table><thead><tr><th>Задание</th><th>Состояние</th><th>Попытки / ошибки</th><th>Доступно с</th><th>Действие</th></tr></thead><tbody>
<?php foreach($rows as $r): $state=$r['state'];$id=(int)$r['id'];$retry=match($provider){'github','infra'=>$state==='dead','logs'=>$state==='failed'&&in_array($r['error_code']??'',['retry_budget','preflight_409'],true),'bots'=>in_array($state,['uncertain','retryable','pending','sending'],true),'sign'=>((int)$r['has_remote']===1&&in_array($state,['pending','partial','provider_error'],true))||($state==='queued'&&(int)$r['attempts']>=REL_BUDGET),default=>false}; ?>
<tr><td>#<?= $id ?><?= $provider==='infra'?' · хост #'.(int)$r['host_id']:'' ?></td><td><?= h($state) ?><?= $provider==='sign'&&(int)$r['attempts']>=REL_BUDGET?' · DLQ':'' ?></td><td><?= (int)$r['attempts'] ?></td><td><?= h($dt($r['available_at'])) ?></td><td>
<?php if($retry): ?><form method="post" class="inline"><?php formFields('reliability.retry') ?><input type="hidden" name="project_id" value="<?= (int)$p ?>"><input type="hidden" name="provider" value="<?= h($provider) ?>"><input type="hidden" name="id" value="<?= $id ?>"><button class="secondary compact"><?= in_array($provider,['bots','sign'],true)?'Сверить / возобновить':'Повторить' ?></button></form><?php endif ?>
<?php if($provider==='logs'&&in_array($state,['failed','expired'],true)): ?><form method="post" class="inline"><?php formFields('reliability.verify') ?><input type="hidden" name="project_id" value="<?= (int)$p ?>"><input type="hidden" name="id" value="<?= $id ?>"><button class="secondary compact">Сверить в Logs</button></form><?php endif ?>
<?php if($provider==='sign'&&$state==='uncertain'): ?><a href="<?= h(url('signing',['project'=>$p,'id'=>$id])) ?>">Проверить ID у провайдера</a><?php endif ?>
<?php if($provider==='bots'&&$state==='failed'): ?><a href="<?= h(url('bots',['project'=>$p,'id'=>$id])) ?>">Штатный безопасный повтор</a><?php endif ?>
</td></tr><?php endforeach ?></tbody></table></div><p>Последние 100 заданий; исходные очереди сохраняют собственные состояния.</p></section><?php endforeach ?>
<section class="panel"><h2>Журнал ошибок и восстановления</h2><p>Технические коды без сырого ответа API. Данные Logs удаляются по его локальной политике хранения.</p><div class="tablewrap"><table><thead><tr><th>Время</th><th>Провайдер / ID</th><th>Результат</th><th>Код</th><th>Ошибки</th></tr></thead><tbody><?php foreach(array_slice($relJournalRows,0,100) as $e): ?><tr><td><?= h($dt($e['created_at'])) ?></td><td><?= h(REL_PROVIDERS[$e['provider']]) ?> #<?= (int)$e['object_id'] ?></td><td><?= h($e['outcome']) ?></td><td><?= h($e['code']) ?></td><td><?= (int)$e['failures'] ?></td></tr><?php endforeach ?></tbody></table></div><?php if(count($relJournalRows)>100): ?><a href="<?= h(url('reliability',['project'=>$p,'before'=>$relJournalRows[99]['id']])) ?>">Предыдущие события</a><?php endif ?>
<form method="post" class="inline"><?php formFields('reliability.retry') ?><input type="hidden" name="project_id" value="<?= (int)$p ?>"><label>Провайдер<select name="provider"><?php selectOptions(REL_PROVIDERS,null) ?></select></label><label>ID задания<input name="id" type="number" min="1" required></label><button class="secondary">Возобновить конкретное задание (MFA)</button></form></section>
<?php endif ?>
